def copy_telegram_ids(apps, schema_editor):
    """Old reports came from the Mini App only: the reporter's Telegram id is on the account."""
    HomeReport = apps.get_model("home", "HomeReport")
    for report in HomeReport.objects.filter(telegram_user_id__isnull=True, user__isnull=False).select_related("user"):
        report.telegram_user_id = report.user.telegram_user_id
        report.save(update_fields=["telegram_user_id"])


